B.aUW=s(["\u0623\u0645\u0627 \u0641\u064a \u0627\u0644\u062d\u064f\u062f\u064a\u0628\u064a\u0629\u060c \u062d\u064a\u0646 \u0628\u062f\u062a \u0628\u0646\u0648\u062f \u0627\u0644\u0635\u0644\u062d \u062b\u0642\u064a\u0644\u0629\u064b \u0639\u0644\u0649 \u0627\u0644\u0646\u0641\u0648\u0633\u060c \u0648\u0643\u0627\u0646 \u0638\u0627\u0647\u0631\u0647\u0627 \u0643\u064e\u0633\u0631\u0629 \u0648\u0636\u0639\u0641\u060c \u0644\u0643\u0646\u0651\u064e \u0623\u0628\u0627 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0631\u0623\u0649 \u0645\u0627 \u0644\u0645 \u062a\u0631\u0647 \u0627\u0644\u0623\u0628\u0635\u0627\u0631\u060c \u0648\u0641\u0647\u0650\u0645 \u0639\u0645\u0642 \u0627\u0644\u062d\u0643\u0645\u0629 \u0641\u064a \u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0646\u0628\u064a \ufdfa.","\u062b\u0645 \u0648\u0642\u0641 \u064a\u064f\u062c\u064a\u0628 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0647\u0648 \u064a\u0642\u0648\u0644: \u064a\u0627 \u0623\u0628\u0627 \u0628\u0643\u0631\u060c \u0623\u0644\u064a\u0633 \u0647\u0630\u0627 \u0646\u0628\u064a\u0651\u064e \u0627\u0644\u0644\u0647 \u062d\u0642\u0651\u064b\u0627\u061f \u0642\u0627\u0644: \u0628\u0644\u0649. \u0642\u0627\u0644: \u0623\u0644\u0633\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0639\u062f\u0648\u0651\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u0628\u0627\u0637\u0644\u061f \u0642\u0627\u0644: \u0628\u0644\u0649. \u0642\u0627\u0644: \u0641\u0644\u0645\u064e \u0646\u0639\u0637\u064a \u0627\u0644\u062f\u0646\u064a\u0651\u0629 \u0641\u064a \u062f\u064a\u0646\u0646\u0627 \u0625\u0630\u0646\u061f \u0642\u0627\u0644: \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0644\u060c \u0625\u0646\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0644\u064a\u0633 \u064a\u0639\u0635\u064a \u0631\u0628\u0647\u060c \u0648\u0647\u0648 \u0646\u0627\u0635\u0631\u0647\u060c \u0641\u0627\u0633\u062a\u0645\u0633\u0643 \u0628\u063a\u0631\u0632\u0647\u060c \u0641\u0648\u0627\u0644\u0644\u0647\u060c \u0625\u0646\u0647 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642.","\u0642\u0627\u0644 \u0639\u0645\u0631: \u0623\u0644\u064a\u0633 \u0643\u0627\u0646 \u064a\u062d\u062f\u062b\u0646\u0627 \u0623\u0646\u0627 \u0633\u0646\u0623\u062a\u064a \u0627\u0644\u0628\u064a\u062a \u0648\u0646\u0637\u0648\u0641 \u0628\u0647\u061f \u0642\u0627\u0644: \u0628\u0644\u0649\u060c \u0623\u0641\u0623\u062e\u0628\u0631\u0643 \u0623\u0646\u0643 \u062a\u0623\u062a\u064a\u0647 \u0627\u0644\u0639\u0627\u0645\u061f \u0642\u0627\u0644: \u0644\u0627. \u0642\u0627\u0644: \u0641\u0625\u0646\u0643 \u0622\u062a\u064a\u0647 \u0648\u0645\u0637\u0648\u0641 \u0628\u0647.","\u064a\u0642\u0648\u0644 \u0639\u0645\u0631: \u0641\u0639\u0645\u0644\u062a\u064f \u0644\u0630\u0644\u0643 \u0623\u0639\u0645\u0627\u0644\u064b\u0627 \u0645\u0646 \u0627\u0644\u0635\u062f\u0642\u0629 \u0648\u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0635\u064a\u0627\u0645\u060c \u0645\u062e\u0627\u0641\u0629\u064b \u0645\u0646 \u0643\u0644\u0627\u0645\u064a \u064a\u0648\u0645\u0626\u0630.","\u0625\u0646 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0643\u0627\u0646 \u064a\u0632\u0646\u064f \u0627\u0644\u0623\u0645\u0648\u0631\u064e \u0628\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u0646\u0628\u0648\u0629\u060c \u064a\u0641\u0647\u0645 \u0633\u064f\u0646\u064e\u0646 \u0627\u0644\u062a\u062f\u0631\u0651\u062c \u0648\u0627\u0644\u062a\u0645\u0643\u064a\u0646 \u0628\u0645\u0646\u0637\u0642 \u0627\u0644\u0648\u062d\u064a \u0644\u0627 \u0628\u0631\u062f\u0651\u0627\u062a \u0627\u0644\u0641\u0639\u0644\u060c \u0641\u062b\u0628\u062a \u062d\u064a\u0646 \u062a\u0631\u062f\u062f \u063a\u064a\u0631\u0647\u060c \u0648\u0644\u0645 \u064a\u062a\u0644\u0639\u062b\u0645 \u0641\u064a \u0627\u0644\u0631\u062f \u0639\u0644\u0649 \u0639\u0645\u0631\u060c \u0648\u0647\u0648 \u064a\u0642\u0648\u0644 \u0644\u0647: \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0644\u060c \u0627\u0633\u062a\u0645\u0633\u0643 \u0628\u063a\u0631\u0632\u0647."],t.s)
B.agE=new A.a("B2_C4_T5","\u0627\u0644\u062d\u062f\u064a\u0628\u064a\u0629 \u0648\u0628\u0635\u064a\u0631\u0629 \u0627\u0644\u0635\u062f\u064a\u0642",B.aUW)
B.aEH=s(["\u0628\u0644\u063a \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0645\u0646 \u0627\u0644\u0642\u0631\u0628 \u0648\u0627\u0644\u0645\u062d\u0628\u0651\u0629 \u0645\u0627 \u0644\u0645 \u064a\u0628\u0644\u063a\u0647 \u0623\u062d\u062f\u060c \u062d\u062a\u0649 \u0625\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0643\u0627\u0646\u0648\u0627 \u064a\u063a\u0628\u0637\u0648\u0646\u0647 \u0639\u0644\u0649 \u0645\u0643\u0627\u0646\u062a\u0647\u060c \u0641\u0642\u062f \u0633\u0623\u0644 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0648\u0645\u064b\u0627: \u0623\u064a\u0651\u064f \u0627\u0644\u0646\u0627\u0633 \u0623\u062d\u0628\u0651 \u0625\u0644\u064a\u0643\u061f \u0642\u0627\u0644: \u0639\u0627\u0626\u0634\u0629. \u0642\u0627\u0644: \u0641\u0645\u0646 \u0627\u0644\u0631\u062c\u0627\u0644\u061f \u0642\u0627\u0644: \u0623\u0628\u0648\u0647\u0627 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a.","\u062d\u062a\u0649 \u0642\u0627\u0644 \ufdfa \u064a\u0648\u0645\u064b\u0627 \u0641\u064a \u062c\u0645\u0639\u064d \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u0647: \u0625\u0646\u0651\u064e \u0623\u0645\u0646\u0651\u064e \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u064a\u0651 \u0641\u064a \u0635\u062d\u0628\u062a\u0647 \u0648\u0645\u0627\u0644\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631\u060c \u0648\u0644\u0648 \u0643\u0646\u062a \u0645\u062a\u062e\u0630\u064b\u0627 \u062e\u0644\u064a\u0644\u064b\u0627 \u063a\u064a\u0631 \u0631\u0628\u064a \u0644\u0627\u062a\u062e\u0630\u062a \u0623\u0628\u0627 \u0628\u0643\u0631\u060c \u0648\u0644\u0643\u0646 \u0623\u062e\u0648\u0651\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0645\u0648\u062f\u062a\u0647 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a.","\u0648\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u062e\u0635 \u0623\u0628\u0627 \u0628\u0643\u0631 \u0628\u0645\u0627 \u0644\u0627 \u064a\u062e\u0635 \u0628\u0647 \u063a\u064a\u0631\u0647 \u0645\u0646 \u0627\u0644\u0623\u0633\u0631\u0627\u0631\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u0623\u0643\u062b\u0631 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0627\u0637\u0644\u0627\u0639\u064b\u0627 \u0639\u0644\u0649 \u0634\u0624\u0648\u0646 \u0627\u0644\u062f\u0648\u0644\u0629\u060c \u0648\u064a\u0633\u062a\u0634\u064a\u0631\u0647\u060c \u0648\u064a\u062b\u0642 \u0628\u0647 \u062b\u0642\u0629 \u0627\u0644\u062d\u0628\u064a\u0628 \u0627\u0644\u0630\u064a \u064a\u0639\u0631\u0641 \u0645\u0639\u062f\u0646 \u0635\u0627\u062d\u0628\u0647\u060c \u0648\u0628\u0645\u0627 \u0648\u0642\u0631 \u0641\u064a \u0642\u0644\u0628\u0647 \u0645\u0646 \u0635\u062f\u0642\u060c \u0648\u0645\u0627 \u062c\u0631\u0649 \u0639\u0644\u0649 \u0644\u0633\u0627\u0646\u0647 \u0645\u0646 \u062d\u0642\u060c \u0648\u0645\u0627 \u0638\u0647\u0631 \u0645\u0646 \u0623\u062b\u0631 \u0625\u064a\u0645\u0627\u0646\u0647 \u0639\u0644\u0649 \u0641\u0639\u0644\u0647."],t.s)
B.ah0=new A.a("B2_C4_T6","\u0623\u062d\u0628\u0651 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa",B.aEH)
B.aVe=s(["\u0643\u0627\u0646 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u062a\u0627\u062c\u0631\u064b\u0627 \u0630\u0627 \u0645\u0627\u0644\u060c \u0644\u0627 \u064a\u0639\u062a\u0645\u062f \u0641\u064a \u0645\u0639\u064a\u0634\u062a\u0647 \u0639\u0644\u0649 \u0643\u0648\u0646\u0647 \u0648\u0632\u064a\u0631\u064b\u0627 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0644\u0627 \u064a\u062c\u0639\u0644 \u0645\u0646 \u0645\u0643\u0627\u0646\u062a\u0647 \u0648\u0633\u064a\u0644\u0629 \u0644\u062a\u062d\u0642\u064a\u0642 \u0645\u0635\u0644\u062d\u0629\u060c \u0628\u0644 \u0639\u0627\u0634 \u0639\u0641\u064a\u0641\u064b\u0627 \u0643\u0631\u064a\u0645 \u0627\u0644\u0646\u0641\u0633\u060c \u064a\u0631\u0649 \u0627\u0644\u0645\u0627\u0644 \u0623\u0645\u0627\u0646\u0629 \u0641\u064a \u0639\u0646\u0642\u0647\u060c \u0648\u0625\u0630\u0627 \u062f\u0639\u0627\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0646\u0641\u0642\u0629\u060c \u0628\u0627\u062f\u0631 \u0628\u0645\u0627 \u0641\u064a \u064a\u062f\u0647\u060c \u0644\u0627 \u064a\u064f\u0639\u0631\u0641 \u0644\u0644\u062a\u0644\u0643\u0624\u060c \u0648\u0644\u0627 \u0644\u0644\u062a\u0631\u062f\u0651\u062f \u0625\u0644\u0649 \u0642\u0644\u0628\u0647 \u0633\u0628\u064a\u0644\u0627\u064b.","\u0644\u0645\u0627 \u0639\u0632\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0644\u0649 \u0627\u0644\u062e\u0631\u0648\u062c \u0625\u0644\u0649 \u062a\u0628\u0648\u0643\u060c \u0641\u064a \u0648\u0642\u062a\u064d \u0627\u0634\u062a\u062f\u0651 \u0641\u064a\u0647 \u0627\u0644\u0643\u0631\u0628\u060c \u0648\u0642\u0644\u0651 \u0641\u064a\u0647 \u0627\u0644\u0645\u0627\u0644\u060c \u0648\u062a\u0628\u0627\u064a\u0646\u062a \u0641\u064a\u0647 \u0627\u0644\u0639\u0632\u0627\u0626\u0645\u060c \u062c\u0627\u0621 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u064a\u062d\u0645\u0644 \u0645\u0627\u0644\u0647 \u0643\u0644\u0651\u0647\u060c \u0641\u0648\u0636\u0639\u0647 \u0628\u064a\u0646 \u064a\u062f\u064a \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0641\u0642\u0627\u0644 \u0644\u0647: \u0645\u0627 \u0623\u0628\u0642\u064a\u062a\u064e \u0644\u0623\u0647\u0644\u0643\u061f \u0642\u0627\u0644: \u0623\u0628\u0642\u064a\u062a\u064f \u0644\u0647\u0645 \u0627\u0644\u0644\u0647\u064e \u0648\u0631\u0633\u0648\u0644\u064e\u0647 - \u0631\u0648\u0627\u0647 \u0627\u0644\u062a\u0631\u0645\u0630\u064a.","\u062d\u062a\u0649 \u0642\u0627\u0644 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0645\u0627 \u0633\u0628\u0642\u062a\u064f \u0623\u0628\u0627 \u0628\u0643\u0631\u064d \u0625\u0644\u0649 \u062e\u064a\u0631\u064d \u0642\u0637\u0651 \u0625\u0644\u0627 \u0633\u0628\u0642\u0646\u064a \u0625\u0644\u064a\u0647.","\u0641\u0647\u0630\u0627 \u0627\u0644\u0641\u0639\u0644 \u064a\u0635\u062f\u0631 \u0645\u0646 \u0642\u0644\u0628\u064d \u0635\u0627\u062f\u0642\u060c \u0648\u0646\u064a\u0651\u0629\u064d \u062e\u0627\u0644\u0635\u0629\u060c \u0648\u062a\u0648\u0643\u0651\u064f\u0644\u064d \u062d\u0642\u0651\u064d\u060c \u0644\u0639\u0645\u0644\u064d \u0644\u0627 \u0631\u062c\u0639\u0629 \u0641\u064a\u0647\u060c \u0648\u0645\u064e\u0646 \u0630\u0627 \u0627\u0644\u0630\u064a \u064a\u0633\u0628\u0642 \u0623\u0628\u0627 \u0628\u0643\u0631\u064d\u060c \u0648\u0642\u062f \u0648\u0647\u0628 \u0644\u0644\u0647 \u0643\u0644\u0651 \u0645\u0627 \u064a\u0645\u0644\u0643\u060c \u0648\u0644\u0645 \u064a\u0644\u062a\u0641\u062a."],t.s)
